 getQueue=reinterpret_cast<PFN_vkGetDeviceQueue>(get(device,"vkGetDeviceQueue"));createPool=reinterpret_cast<PFN_vkCreateCommandPool>(get(device,"vkCreateCommandPool"));destroyPool=reinterpret_cast<PFN_vkDestroyCommandPool>(get(device,"vkDestroyCommandPool"));resetPool=reinterpret_cast<PFN_vkResetCommandPool>(get(device,"vkResetCommandPool"));allocate=reinterpret_cast<PFN_vkAllocateCommandBuffers>(get(device,"vkAllocateCommandBuffers"));begin=reinterpret_cast<PFN_vkBeginCommandBuffer>(get(device,"vkBeginCommandBuffer"));end=reinterpret_cast<PFN_vkEndCommandBuffer>(get(device,"vkEndCommandBuffer"));barrier=reinterpret_cast<PFN_vkCmdPipelineBarrier>(get(device,"vkCmdPipelineBarrier"));blit=reinterpret_cast<PFN_vkCmdBlitImage>(get(device,"vkCmdBlitImage"));clear=reinterpret_cast<PFN_vkCmdClearColorImage>(get(device,"vkCmdClearColorImage"));createFence=reinterpret_cast<PFN_vkCreateFence>(get(device,"vkCreateFence"));destroyFence=reinterpret_cast<PFN_vkDestroyFence>(get(device,"vkDestroyFence"));resetFence=reinterpret_cast<PFN_vkResetFences>(get(device,"vkResetFences"));waitFence=reinterpret_cast<PFN_vkWaitForFences>(get(device,"vkWaitForFences"));createSemaphore=reinterpret_cast<PFN_vkCreateSemaphore>(get(device,"vkCreateSemaphore"));destroySemaphore=reinterpret_cast<PFN_vkDestroySemaphore>(get(device,"vkDestroySemaphore"));acquire=reinterpret_cast<PFN_vkAcquireNextImageKHR>(get(device,"vkAcquireNextImageKHR"));submit=reinterpret_cast<PFN_vkQueueSubmit>(get(device,"vkQueueSubmit"));present=reinterpret_cast<PFN_vkQueuePresentKHR>(get(device,"vkQueuePresentKHR"));idle=reinterpret_cast<PFN_vkQueueWaitIdle>(get(device,"vkQueueWaitIdle"));if(!blit||!getQueue||!createPool||!destroyPool||!resetPool||!allocate||!begin||!end||!barrier||!clear||!createFence||!destroyFence||!resetFence||!waitFence||!createSemaphore||!destroySemaphore||!acquire||!submit||!present||!idle)throw std::runtime_error("presentation dispatch missing");
