check(resetFence(device,1,&acquired));uint32_t index=0;check(acquire(device,swapchain,30000000000ull,VK_NULL_HANDLE,acquired,&index));check(waitFence(device,1,&acquired,VK_TRUE,30000000000ull));if(index>=images.size())throw std::runtime_error("acquired image index");if(frame)check(resetPool(device,pool,0));VkCommandBufferBeginInfo start{};start.sType=VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO;start.flags=VK_COMMAND_BUFFER_USAGE_ONE_TIME_SUBMIT_BIT;check(begin(command,&start));VkImageMemoryBarrier transition{};transition.sType=VK_STRUCTURE_TYPE_IMAGE_MEMORY_BARRIER;transition.oldLayout=VK_IMAGE_LAYOUT_UNDEFINED;transition.newLayout=VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL;transition.dstAccessMask=VK_ACCESS_TRANSFER_WRITE_BIT;transition.srcQueueFamilyIndex=transition.dstQueueFamilyIndex=VK_QUEUE_FAMILY_IGNORED;transition.image=images[index];transition.subresourceRange={VK_IMAGE_ASPECT_COLOR_BIT,0,1,0,1};barrier(command,VK_PIPELINE_STAGE_TOP_OF_PIPE_BIT,VK_PIPELINE_STAGE_TRANSFER_BIT,0,0,nullptr,0,nullptr,1,&transition);VkClearColorValue color{};color.float32[frame%3]=1;color.float32[3]=1;if(source){const uint32_t availableWidth=extent.width-reservedLeft;auto fit=viewportFitCandidate(sourceWidth,sourceHeight,availableWidth,extent.height-reservedBottom);fit.x+=int32_t(reservedLeft);VkClearColorValue background{};background.float32[3]=1;clear(command,images[index],VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL,&background,1,&transition.subresourceRange);VkMemoryBarrier clearToBlit{};clearToBlit.sType=VK_STRUCTURE_TYPE_MEMORY_BARRIER;clearToBlit.srcAccessMask=clearToBlit.dstAccessMask=VK_ACCESS_TRANSFER_WRITE_BIT;barrier(command,VK_PIPELINE_STAGE_TRANSFER_BIT,VK_PIPELINE_STAGE_TRANSFER_BIT,0,1,&clearToBlit,0,nullptr,0,nullptr);VkImageBlit region{};region.srcSubresource={VK_IMAGE_ASPECT_COLOR_BIT,0,0,1};region.dstSubresource=region.srcSubresource;region.srcOffsets[1]={int32_t(sourceWidth),int32_t(sourceHeight),1};region.dstOffsets[0]={fit.x,fit.y,0};region.dstOffsets[1]={fit.x+fit.width,fit.y+fit.height,1};std::cout<<"viewport_fit x="<<fit.x<<" y="<<fit.y<<" width="<<fit.width<<" height="<<fit.height<<" background=black reserved_bottom="<<reservedBottom<<" reserved_left="<<reservedLeft<<"\n";blit(command,source,VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL,images[index],VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL,1,&region,VK_FILTER_NEAREST);}else clear(command,images[index],VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL,&color,1,&transition.subresourceRange);transition.oldLayout=VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL;transition.newLayout=VK_IMAGE_LAYOUT_PRESENT_SRC_KHR;transition.srcAccessMask=VK_ACCESS_TRANSFER_WRITE_BIT;transition.dstAccessMask=0;barrier(command,VK_PIPELINE_STAGE_TRANSFER_BIT,VK_PIPELINE_STAGE_BOTTOM_OF_PIPE_BIT,0,0,nullptr,0,nullptr,1,&transition);check(end(command));VkSubmitInfo submission{};submission.sType=VK_STRUCTURE_TYPE_SUBMIT_INFO;submission.commandBufferCount=1;submission.pCommandBuffers=&command;submission.signalSemaphoreCount=1;submission.pSignalSemaphores=&rendered.at(index);check(resetFence(device,1,&submitted));check(submit(queue,1,&submission,submitted));pending=true;VkResult imageResult=VK_SUCCESS;VkPresentInfoKHR presentation{};presentation.sType=VK_STRUCTURE_TYPE_PRESENT_INFO_KHR;presentation.waitSemaphoreCount=1;presentation.pWaitSemaphores=&rendered.at(index);presentation.swapchainCount=1;presentation.pSwapchains=&swapchain;presentation.pImageIndices=&index;presentation.pResults=&imageResult;check(present(queue,&presentation));check(imageResult);check(waitFence(device,1,&submitted,VK_TRUE,30000000000ull));pending=false;std::cout<<"presented_frame="<<frame<<" image="<<index<<" acquire_fence=completed present_result="<<imageResult<<'\n';
